<main class="container section-space professional-directory"><section class="v10-page-head"><div><span class="eyebrow">TEKNİK EKİP AĞI</span><h1>Teknik Direktör Bul</h1><p>Şehir, lisans, unvan ve çalışma durumuna göre teknik direktör ve antrenör profillerini keşfet.</p></div><a class="btn btn-primary" href="/teknik-direktor-profilim">Teknik Profilimi Oluştur</a></section><section class="panel professional-filters"><form method="get" action="/teknik-direktorler" class="form-row-5" data-location-group><label>İl<select name="province" data-location-province><?= TurkeyLocation::provinceOptions((string)($filters['province']??''),'Tüm iller') ?></select></label><label>İlçe<select name="district" data-location-district><?= TurkeyLocation::districtOptions((string)($filters['province']??''),(string)($filters['district']??''),'Tüm ilçeler') ?></select></label><label>Unvan<input name="public_title" value="<?= htmlspecialchars((string)($filters['public_title']??'')) ?>" placeholder="Teknik Direktör"></label><label>Durum<select name="intent"><option value="">Tümü</option><option value="open_to_offers" <?= ($filters['intent']??'')==='open_to_offers'?'selected':'' ?>>Tekliflere açık</option><option value="looking_for_team" <?= ($filters['intent']??'')==='looking_for_team'?'selected':'' ?>>Takım arıyor</option><option value="showcase" <?= ($filters['intent']??'')==='showcase'?'selected':'' ?>>Profil vitrini</option></select></label><button class="btn btn-dark" type="submit">Filtrele</button></form></section><section class="professional-card-grid"><?php foreach($rows as $c): ?><article class="panel professional-card"><div class="professional-card-head"><div class="professional-avatar"><?php if(!empty($c['avatar_path'])):?><img src="<?= htmlspecialchars((string)$c['avatar_path']) ?>" alt=""><?php else:?><span><?= htmlspecialchars(strtoupper(substr((string)$c['display_name'],0,1))) ?></span><?php endif;?></div><div><span class="eyebrow"><?= htmlspecialchars(mb_strtoupper((string)$c['public_title'])) ?></span><h2><?= htmlspecialchars((string)$c['display_name']) ?><?= VerificationBadge::render($c) ?></h2><p><?= htmlspecialchars((string)$c['district'].', '.(string)$c['province']) ?></p></div></div><div class="professional-meta"><span><?= htmlspecialchars((string)($c['license_level']?:'Lisans belirtilmedi')) ?></span><span><?= ($c['intent']??'')==='open_to_offers'?'Tekliflere açık':(($c['intent']??'')==='looking_for_team'?'Takım arıyor':'Profil vitrini') ?></span><?php if(($c['license_status']??'')==='verified'):?><span class="pro-license-ok">Antrenör lisansı doğrulandı</span><?php endif;?></div><a class="btn btn-soft btn-small" href="/teknik-direktor/<?= rawurlencode((string)$c['slug']) ?>">Profili Gör</a></article><?php endforeach;?><?php if(!$rows):?><div class="panel v9-empty"><strong>Bu filtrelerde yayınlanmış teknik direktör yok.</strong></div><?php endif;?></section></main><?php require __DIR__.'/../layouts/footer.php'; ?>
